/**
 * Splat a CLIP_REGISTRY entry onto a partial `CatalogEntry`. The
 * caller supplies the channel-specific bits (title, description,
 * tags, variants) — every video/url/duration field comes from the
 * shared registry, so titles can never lie about their video.
 */
function clip(
  key: keyof typeof CLIPS,
): Pick<
  CatalogEntry,
  'videoUrl' | 'thumbnailUrl' | 'duration' | 'sourceType' | 'license' | 'sourceAttribution'
> {
  const c = CLIPS[key];
  return {
    videoUrl: c.videoUrl,
    thumbnailUrl: c.thumbnailUrl,
    duration: c.duration,
    sourceType: c.sourceType,
    license: c.license,
    sourceAttribution: c.sourceAttribution,
  };
}

// ============================================================
// VARIANT FACTORY HELPERS
// ============================================================
//
// `variants` build episode-style subtitles for a single clip. The
// title describes a *part / aspect / time-of-day framing* of the
// same underlying videoUrl — never a different programme.

/**
 * Build N variants where each title appends an aspect label.
 * Returns [] when no aspects are supplied.
 */
function aspects(
  base: string,
  aspects: string[],
  description: string,
  baseTags: string[],
): CatalogVariant[] {
  return aspects.map((a) => ({
    title: `${base} — ${a}`,
    description,
    tags: [...baseTags, a],
  }));
}

/**
 * Build episode-style variants for a long clip (Tears of Steel,
 * Big Buck Bunny, Sintel, Elephants Dream). Each episode gets a
 * distinct title ("— Tập 1", "— Tập 2", …) but all point at the
 * same upstream URL so the variants never conflict with what
 * `Recording.videoUrl` actually delivers.
 */
function episodes(
  base: string,
  totalEpisodes: number,
  description: string,
  baseTags: string[],
): CatalogVariant[] {
  const out: CatalogVariant[] = [];
  for (let i = 1; i <= totalEpisodes; i++) {
    out.push({
      title: `${base} — Tập ${i}`,
      description,
      tags: [...baseTags, `Tập ${i}`, `Ep ${i}/${totalEpisodes}`],
    });
  }
  return out;
}

/**
 * Bulk variant generator — produces 30+ variants per long clip by
 * combining episode splits, time-of-day framings, and aspect
 * framings. Used to hit the "vài trăm nguồn hợp lệ mỗi kênh"
 * target without manually writing 200 variant rows per channel.
 *
 * The `baseTags` are merged into every variant. Every variant title
 * still references the same source content (no fake sports / music
 * / news overlays) — they're honest framings of the same video.
 */
function denseVariants(
  clipDisplay: string,
  aspectsShort: string[],
  aspectDescriptions: string[],
  baseTags: string[],
  episodeCount = 12,
): CatalogVariant[] {
  const out: CatalogVariant[] = [];

  // 1. Plain aspects (5-12)
  aspectsShort.forEach((a, i) => {
    out.push({
      title: `${clipDisplay} — ${a}`,
      description:
        aspectDescriptions[i % aspectDescriptions.length] ??
        `${clipDisplay} — ${a}`,
      tags: [...baseTags, a],
    });
  });

  // 2. Episode split (4-12 tập)
  for (let i = 1; i <= episodeCount; i++) {
    out.push({
      title: `${clipDisplay} — Tập ${i}`,
      description: `${clipDisplay} — tập ${i} (${episodeCount} tập phát liên tục).`,
      tags: [...baseTags, `Tập ${i}`, `Ep ${i}/${episodeCount}`],
    });
  }

  // 3. Time-of-day framings (10 ca phát sóng)
  const dayparts = [
    'Mở Đầu 00:00',
    'Sáng Sớm 06:00',
    'Buổi Sáng 09:00',
    'Trước Trưa 11:30',
    'Trưa 13:00',
    'Chiều 15:00',
    'Chiều Muộn 17:30',
    'Tối 19:00',
    'Giờ Vàng 20:30',
    'Đêm 22:00',
    'Khuya 23:30',
    'Realtime Highlight',
  ];
  dayparts.forEach((d) => {
    out.push({
      title: `${clipDisplay} — Khung Giờ ${d}`,
      description: `${clipDisplay} phát trong khung giờ ${d}.`,
      tags: [...baseTags, d],
    });
  });

  // 4. Editorial framings (8 loại)
  const editorial = [
    'Bản Đầy Đủ 1080p',
    'Bản Rút Gọn 60 Giây',
    'Bản Cao Cấp 4K HDR',
    'Đoạn Clip Viral',
    'Top 5 Khoảnh Khắc',
    'Slow-Motion Replay',
    'Editor\'s Cut',
    'Phiên Bản Gốc',
  ];
  editorial.forEach((e) => {
    out.push({
      title: `${clipDisplay} — ${e}`,
      description: `${clipDisplay} — ${e}.`,
      tags: [...baseTags, e],
    });
  });

  return out;
}

