// ============================================================
// ROW FACTORY
// ============================================================

/**
 * One concrete `Recording` row derived from a catalog entry.
 * We always emit at least one row (the base), plus one per variant.
 */
export interface CatalogRow {
  id: string;
  channelSlug: string;
  title: string;
  description: string;
  videoUrl: string;
  thumbnailUrl: string;
  duration: number;
  sourceType: StreamSourceType;
  license: ContentLicense;
  sourceAttribution: string;
  thumbnailAttribution?: string;
  tags: string[];
}

/**
 * Expand a single catalog entry into one-or-more concrete rows.
 * Each entry produces 1 + `variants.length` rows that all point at
 * the same upstream `videoUrl` but carry distinct metadata. This
 * gives the EPG filler enough "slots" to rotate through without
 * repeating the same title/description adjacent to itself.
 */
export function expandEntry(entry: CatalogEntry): CatalogRow[] {
  const baseId = makeDeterministicId(entry.channelSlug, entry.baseTitle);
  const rows: CatalogRow[] = [
    {
      id: baseId,
      channelSlug: entry.channelSlug,
      title: entry.baseTitle,
      description: entry.baseDescription,
      videoUrl: entry.videoUrl,
      thumbnailUrl: entry.thumbnailUrl,
      duration: entry.duration,
      sourceType: entry.sourceType,
      license: entry.license,
      sourceAttribution: entry.sourceAttribution,
      thumbnailAttribution: entry.thumbnailAttribution,
      tags: [...entry.defaultTags],
    },
  ];
  for (let i = 0; i < entry.variants.length; i++) {
    const v = entry.variants[i];
    const variantTitle = v.title || entry.baseTitle;
    const variantDesc = v.description || entry.baseDescription;
    rows.push({
      id: makeDeterministicId(entry.channelSlug, `${entry.baseTitle}::v${i + 1}::${variantTitle}`),
      channelSlug: entry.channelSlug,
      title: variantTitle,
      description: variantDesc,
      videoUrl: entry.videoUrl,
      thumbnailUrl: entry.thumbnailUrl,
      duration: entry.duration,
      sourceType: entry.sourceType,
      license: entry.license,
      sourceAttribution: entry.sourceAttribution,
      thumbnailAttribution: entry.thumbnailAttribution,
      tags: Array.from(new Set([...entry.defaultTags, ...v.tags])),
    });
  }
  return rows;
}

export function expandAll(): CatalogRow[] {
  return LIBRARY.flatMap(expandEntry);
}

export function byChannel(): Map<string, CatalogRow[]> {
  const map = new Map<string, CatalogRow[]>();
  for (const row of expandAll()) {
    const list = map.get(row.channelSlug) ?? [];
    list.push(row);
    map.set(row.channelSlug, list);
  }
  return map;
}

/**
 * Stable UUID-shaped ID derived from (channel, title). Same input
 * always yields the same ID so the seed is idempotent (re-runs
 * upsert instead of duplicating).
 */
export function makeDeterministicId(channelSlug: string, title: string): string {
  // Lightweight deterministic hash; avoids requiring `crypto` so the
  // module can be imported in browser tooling / docs without a Node
  // polyfill. Output is 32 hex chars + dashes shaped like a UUID.
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;
  const s = `${channelSlug}::${title}`;
  for (let i = 0; i < s.length; i++) {
    const ch = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  const hex =
    (h1 >>> 0).toString(16).padStart(8, '0') +
    (h2 >>> 0).toString(16).padStart(8, '0') +
    ((h1 ^ h2) >>> 0).toString(16).padStart(8, '0') +
    ((h1 + h2) >>> 0).toString(16).padStart(8, '0');
  return `99999999-${hex.slice(0, 4)}-${hex.slice(4, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 24)}`;
}

export const TOTAL_CHANNELS = new Set(LIBRARY.map((e) => e.channelSlug)).size;
export const TOTAL_ENTRIES_AFTER_EXPANSION = expandAll().length;
